import { withAuth } from 'next-auth/middleware';
import { NextResponse } from 'next/server';

export default withAuth(
  function middleware(req) {
    const token = req.nextauth.token;
    const path = req.nextUrl.pathname;

    // Role-based restrictions for UI pages
    if (path.startsWith('/departments') && token?.role === 'EMPLOYEE') {
      // Employees can view dashboard, profile, attendance, leaves, but departments is HR/Admin only
      return NextResponse.redirect(new URL('/dashboard', req.url));
    }

    return NextResponse.next();
  },
  {
    callbacks: {
      authorized: ({ token }) => !!token,
    },
    pages: {
      signIn: '/login',
    },
  }
);

export const config = {
  matcher: [
    '/dashboard/:path*',
    '/employees/:path*',
    '/departments/:path*',
    '/attendance/:path*',
    '/leaves/:path*',
  ],
};
